<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'
import PageHeader from '../../components/BasePageHeader.vue'
import BaseSelect from '../../components/BaseSelect.vue'
import { api, getErrorMessage } from '../../api/request'
import { useToast } from '../../composables/useToast'

type Row = Record<string, any>
const { show } = useToast()
const active = ref('assessment'), busy = ref('')
const questionnaires = ref<Row[]>([]), sessions = ref<Row[]>([]), questionnaire = ref<Row|null>(null), activeSession = ref<Row|null>(null), answers = ref<Record<string, number>>({}), scores = ref<Row|null>(null)
const portrait = ref<Row|null>(null), portraitVersions = ref<Row[]>([]), portraitFeedback = ref('HELPFUL'), portraitComment = ref('')
const directions = ref<Row[]>([]), favorites = ref<Row[]>([]), recommendation = ref<Row|null>(null), recommendationRuns = ref<Row[]>([]), recPath = ref(''), feedbackComments = ref<Record<string,string>>({})
const goals = ref<Row|null>(null), goalVersions = ref<Row[]>([]), primaryDirectionId = ref(''), backupDirectionId = ref(''), goalReason = ref('')
const plan = ref<Row|null>(null), plans = ref<Row[]>([]), tasks = ref<Row[]>([]), taskMonth = ref(new Date().toISOString().slice(0,7)), taskStatus = ref(''), taskForm = ref({ title:'', type:'LEARNING', estHours:'', deadline:'', abilityTags:'', note:'' }), taskEdits = ref<Record<string,Row>>({}), checkins = ref<Record<string,Row>>({})
const reviews = ref<Row[]>([]), reviewForm = ref({ cycle:'', done:'', undone:'', interest:'', ability:'', next:'' }), reminders = ref<Row[]>([]), unreadCount = ref(0)
const selectedQuestionnaire = ref('')
const tabs = [{value:'assessment',label:'生涯测评'},{value:'portrait',label:'个人画像'},{value:'recommendation',label:'方向推荐'},{value:'goals',label:'目标与计划'},{value:'tasks',label:'任务与复盘'}]
const questionnaireOptions = computed(()=>questionnaires.value.map(q=>({value:String(q.id),label:`${q.name || q.typeName}（${q.questionCount || 0} 题）`})))
const directionOptions = computed(()=>directions.value.map(d=>({value:String(d.id),label:String(d.name)})));
const pathOptions = [{value:'',label:'全部路径'},{value:'graduate',label:'国内升学'},{value:'employment',label:'就业发展'},{value:'overseas',label:'出国留学'}]
const taskStatusOptions = [{value:'',label:'全部状态'},{value:'PENDING',label:'待开始'},{value:'DOING',label:'进行中'},{value:'DONE',label:'已完成'},{value:'DELAYED',label:'已延期'},{value:'ABANDONED',label:'已放弃'}]
const taskTypeOptions = [{value:'LEARNING',label:'学习'},{value:'PRACTICE',label:'实践'},{value:'CAREER',label:'职业探索'},{value:'REVIEW',label:'复盘'}]

function list(data:any):Row[]{ return Array.isArray(data) ? data : (data?.list || data?.items || []) }
function error(e:unknown){ show(getErrorMessage(e)) }
async function run(key:string, action:()=>Promise<any>, reload=true){ busy.value=key; try { const result=await action(); show('操作已完成'); if(reload) await loadAll(); return result } catch(e){ error(e) } finally { busy.value='' } }
async function loadAll(){
  try {
    const data:any[] = await Promise.all([api.student.questionnaires(), api.student.assessmentSessions(), api.student.latestPortrait(), api.student.portraitVersions(), api.student.directions(), api.student.favorites(), api.student.recommendationLatest(), api.student.recommendationRuns(), api.student.goals(), api.student.goalVersions(), api.student.latestPlan(), api.student.plans(), api.student.tasks({month:taskMonth.value,status:taskStatus.value}), api.student.reviews(), api.student.reminders(), api.student.unreadReminderCount()])
    questionnaires.value=list(data[0]); sessions.value=list(data[1]); portrait.value=data[2]||null; portraitVersions.value=list(data[3]); directions.value=list(data[4]); favorites.value=list(data[5]); recommendation.value=data[6]||null; recommendationRuns.value=list(data[7]); goals.value=data[8]||null; goalVersions.value=list(data[9]); plan.value=data[10]||null; plans.value=list(data[11]); tasks.value=list(data[12]); reviews.value=list(data[13]); reminders.value=list(data[14]); unreadCount.value=Number(data[15]?.count || 0)
    primaryDirectionId.value=goals.value?.primary?.directionId || primaryDirectionId.value; backupDirectionId.value=goals.value?.backup?.directionId || backupDirectionId.value
  } catch(e){ error(e) }
}
async function openQuestionnaire(){
  if(!selectedQuestionnaire.value) return
  await run('open-questionnaire', async()=>{ questionnaire.value=await api.student.questionnaire(selectedQuestionnaire.value) as Row; return questionnaire.value }, false)
}
async function startAssessment(){
  const created=await run('start-assessment', ()=>api.student.createAssessment({questionnaireId:selectedQuestionnaire.value}), false) as Row|undefined
  if(created){ activeSession.value=created; answers.value={}; if(!questionnaire.value) await openQuestionnaire(); await loadAll() }
}
function answerItems(){ return (questionnaire.value?.questions || []).flatMap((q:Row)=>{ const value=answers.value[q.id]; if(value===undefined) return []; return [{questionId:q.id, ...(q.type==='RATING'?{ratingValue:value}:{optionIndex:value})}] }) }
async function saveAnswers(finished=false){ if(!activeSession.value) return; await run('save-answers', ()=>api.student.saveAssessment(activeSession.value!.id,{answers:answerItems(),finished}), false) }
async function submitAssessment(){ if(!activeSession.value) return; const result=await run('submit-assessment', ()=>api.student.submitAssessment(activeSession.value!.id), false); if(result){ scores.value=result as Row; await loadAll() } }
async function viewSession(session:Row){ activeSession.value=session; selectedQuestionnaire.value=String(session.questionnaireId); await openQuestionnaire(); if(session.status==='SCORED') scores.value=await api.student.assessmentScores(session.id) as Row }
function flatLines(values:any){ return Array.isArray(values) ? values.filter(Boolean).join('；') : '—' }
async function refreshPortrait(){ await run('refresh-portrait', api.student.refreshPortrait) }
async function savePortraitFeedback(){ if(!portrait.value?.id) return; await run('portrait-feedback',()=>api.student.portraitFeedback(portrait.value!.id,{feedbackType:portraitFeedback.value,comment:portraitComment.value})) }
async function toggleFavorite(direction:Row){ await run(`favorite-${direction.id}`,()=>direction.favorited?api.student.removeFavorite(direction.id):api.student.addFavorite(direction.id)) }
async function filterDirections(){
  await run('directions', async()=>{
    directions.value=list(await api.student.directions(recPath.value || undefined))
    return directions.value
  }, false)
}
async function makeRecommendation(){ await run('recommendation',()=>api.student.createRecommendation({pathFilter:recPath.value || undefined})) }
async function saveRecFeedback(result:Row,type:string){ await run(`rec-feedback-${result.resultId}`,()=>api.student.recommendationFeedback(result.resultId,{feedbackType:type,comment:feedbackComments.value[result.resultId]||''})) }
async function saveGoal(change=false){ const data={primaryDirectionId:primaryDirectionId.value||undefined,backupDirectionId:backupDirectionId.value||undefined,changeReason:goalReason.value||undefined}; await run('goal',()=>change?api.student.updateGoals(data):api.student.saveGoals(data)) }
async function draftPlan(){ await run('draft-plan',()=>api.student.draftPlan({directionId:primaryDirectionId.value||undefined,useAi:true})) }
async function confirmPlan(){ await run('confirm-plan',()=>api.student.confirmPlan({confirm:true})) }
async function saveTask(){ const tags=taskForm.value.abilityTags.split(/[，,\n]/).map(item=>item.trim()).filter(Boolean); await run('create-task',()=>api.student.createTask({month:taskMonth.value,title:taskForm.value.title,type:taskForm.value.type,estHours:Number(taskForm.value.estHours||0),deadline:taskForm.value.deadline||undefined,abilityTags:tags,note:taskForm.value.note||undefined})); taskForm.value={title:'',type:'LEARNING',estHours:'',deadline:'',abilityTags:'',note:''} }
function editTask(task:Row){ taskEdits.value[task.id]={month:task.month,title:task.title,estHours:task.estHours,status:task.status,note:task.note||'',reason:''} }
async function updateTask(id:string){ const data=taskEdits.value[id]; if(data) await run(`update-task-${id}`,()=>api.student.updateTask(id,data)) }
async function checkinTask(id:string){ const data=checkins.value[id]||{}; await run(`checkin-${id}`,()=>api.student.checkinTask(id,data)); delete checkins.value[id] }
async function createReview(){ await run('create-review',()=>api.student.createReview({cycle:reviewForm.value.cycle,content:{done:reviewForm.value.done,undone:reviewForm.value.undone,interest:reviewForm.value.interest,ability:reviewForm.value.ability,next:reviewForm.value.next}})) }
async function reviewAction(id:string, action:'submit'|'summary'|'guidance'){ if(action==='submit') await run(`submit-${id}`,()=>api.student.submitReview(id)); else if(action==='summary') await run(`summary-${id}`,()=>api.student.summarizeReview(id)); else await run(`guidance-${id}`,()=>api.student.requestGuidance(id,{message:'希望辅导员给予下一阶段建议'})) }
async function readReminder(id:string){ await run(`read-${id}`,()=>api.student.markReminderRead(id)) }
onMounted(loadAll)
</script>

<template>
  <PageHeader eyebrow="生涯发展" title="测评、画像与行动计划" description="完成测评、查看画像和推荐，并把方向选择转化为可执行的任务与复盘。"/>
  <nav class="tab-bar development-tabs"><button v-for="tab in tabs" :key="tab.value" :class="{active:active===tab.value}" @click="active=tab.value">{{tab.label}}<small v-if="tab.value==='tasks'&&unreadCount">{{unreadCount}}</small></button></nav>

  <section v-if="active==='assessment'" class="development-stack">
    <article class="card"><p class="eyebrow">测评问卷</p><h2>选择问卷并作答</h2><div class="inline-form"><BaseSelect v-model="selectedQuestionnaire" :options="questionnaireOptions" placeholder="请选择测评问卷"/><button class="outline-btn" :disabled="!selectedQuestionnaire||busy==='open-questionnaire'" @click="openQuestionnaire">查看题目</button><button class="primary-btn" :disabled="!selectedQuestionnaire||busy==='start-assessment'" @click="startAssessment">开始测评</button></div><p class="muted">测评过程可反复保存；提交后系统会计算六个维度的得分。</p></article>
    <article v-if="questionnaire&&activeSession" class="card question-card"><div class="section-head"><div><p class="eyebrow">{{questionnaire.questionnaire?.typeName || questionnaire.questionnaire?.name}}</p><h2>正在作答</h2></div><span>{{answerItems().length}} / {{questionnaire.questions?.length||0}} 题已答</span></div><fieldset v-for="(question,index) in questionnaire.questions||[]" :key="question.id"><legend>{{index+1}}. {{question.text}}</legend><div v-if="question.type==='RATING'" class="choice-row"><button v-for="n in 5" :key="n" :class="{selected:answers[question.id]===n}" @click="answers[question.id]=n">{{question.labels?.[n-1] || n}}</button></div><div v-else class="choice-column"><button v-for="(option,index) in question.options||[]" :key="option.id" :class="{selected:answers[question.id]===index}" @click="answers[question.id]=index">{{option.text}}</button></div></fieldset><div class="form-actions"><button class="outline-btn" :disabled="busy==='save-answers'" @click="saveAnswers(false)">保存进度</button><button class="primary-btn" :disabled="answerItems().length!==(questionnaire.questions||[]).length||busy==='submit-assessment'" @click="submitAssessment">提交并评分</button></div></article>
    <article v-if="scores" class="card"><p class="eyebrow">评分结果</p><h2>六维能力概览</h2><div class="metric-grid"><div v-for="item in scores.dimensionScores||[]" :key="item.dimensionCode"><small>{{item.dimensionName}}</small><b>{{Number(item.score||0).toFixed(1)}}</b></div></div></article>
    <article class="card"><p class="eyebrow">历史记录</p><h2>我的测评会话</h2><div class="simple-list"><button v-for="session in sessions" :key="session.id" @click="viewSession(session)"><b>{{session.questionnaireName || '测评问卷'}}</b><span>{{session.answeredQuestions||0}} / {{session.totalQuestions||0}} 题 · {{session.status}}</span></button><p v-if="!sessions.length" class="empty">尚未创建测评会话</p></div></article>
  </section>

  <section v-else-if="active==='portrait'" class="development-stack"><article class="card"><div class="section-head"><div><p class="eyebrow">个人画像</p><h2>生涯发展画像</h2></div><button class="primary-btn" :disabled="busy==='refresh-portrait'" @click="refreshPortrait">更新画像</button></div><template v-if="portrait"><p>{{portrait.summary}}</p><div class="metric-grid"><div v-for="item in portrait.dimensions||[]" :key="item.key"><small>{{item.name}}</small><b>{{Number(item.score||0).toFixed(1)}}</b></div></div><div class="two-column"><div><h3>优势</h3><p>{{flatLines(portrait.strengths)}}</p></div><div><h3>待探索</h3><p>{{flatLines(portrait.explore)}}</p></div></div><div class="inline-form"><BaseSelect v-model="portraitFeedback" :options="[{value:'HELPFUL',label:'有帮助'},{value:'MISMATCH',label:'与我不符'},{value:'NEUTRAL',label:'一般'}]"/><input v-model.trim="portraitComment" placeholder="补充反馈（可选）"><button class="outline-btn" @click="savePortraitFeedback">提交反馈</button></div></template><p v-else class="empty">尚无画像；请先完善档案或完成测评。</p></article><article class="card"><p class="eyebrow">版本记录</p><h2>历史画像</h2><div class="simple-list"><div v-for="item in portraitVersions" :key="item.id"><b>第 {{item.version}} 版</b><span>完整度 {{item.completeness||0}}% · {{item.generatedAt||'—'}}</span></div><p v-if="!portraitVersions.length" class="empty">暂无历史版本</p></div></article></section>

  <section v-else-if="active==='recommendation'" class="development-stack"><article class="card"><p class="eyebrow">发展方向</p><h2>浏览与收藏</h2><div class="inline-form"><BaseSelect v-model="recPath" :options="pathOptions"/><button class="outline-btn" @click="filterDirections">筛选方向</button><button class="primary-btn" :disabled="busy==='recommendation'" @click="makeRecommendation">生成推荐</button></div><div class="direction-grid"><article v-for="item in directions" :key="item.id"><h3>{{item.name}}</h3><p>{{item.intro||'暂无简介'}}</p><button class="outline-btn" @click="toggleFavorite(item)">{{item.favorited?'取消收藏':'收藏方向'}}</button></article></div></article><article class="card"><p class="eyebrow">推荐结果</p><h2>{{recommendation?.ruleVersion ? `规则 ${recommendation.ruleVersion}`:'尚未生成推荐'}}</h2><div v-if="recommendation?.results" class="simple-list"><div v-for="result in recommendation.results" :key="result.resultId"><b>第 {{result.rank}} 位 · {{result.directionId}}</b><span>匹配度 {{Number(result.score||0).toFixed(1)}} · {{flatLines(result.reasons)}}</span><div class="inline-form"><input v-model.trim="feedbackComments[result.resultId]" placeholder="反馈说明（可选）"><button class="outline-btn" @click="saveRecFeedback(result,'INTERESTED')">感兴趣</button><button class="outline-btn" @click="saveRecFeedback(result,'NOT_INTERESTED')">不感兴趣</button></div></div></div><p v-else class="empty">请完成画像后生成个性化方向推荐。</p></article><article class="card"><p class="eyebrow">我的收藏</p><div class="chip-row"><span v-for="item in favorites" :key="item.id">{{item.name}}</span><p v-if="!favorites.length" class="empty">暂未收藏方向</p></div></article></section>

  <section v-else-if="active==='goals'" class="development-stack"><article class="card"><p class="eyebrow">发展目标</p><h2>选择主方向与备选方向</h2><div class="two-column"><label>主方向<BaseSelect v-model="primaryDirectionId" :options="directionOptions" placeholder="请选择主方向"/></label><label>备选方向<BaseSelect v-model="backupDirectionId" :options="directionOptions" placeholder="可选"/></label></div><textarea v-model.trim="goalReason" placeholder="变更原因或补充说明（可选）"/><div class="form-actions"><button class="outline-btn" @click="saveGoal(false)">保存目标</button><button class="primary-btn" @click="saveGoal(true)">变更目标</button></div><p class="muted">当前主方向：{{goals?.primary?.name||'未设置'}}；备选方向：{{goals?.backup?.name||'未设置'}}。</p></article><article class="card"><div class="section-head"><div><p class="eyebrow">学期计划</p><h2>{{plan?.goalSummary || '尚未生成计划'}}</h2></div><div><button class="outline-btn" @click="draftPlan">生成草案</button><button v-if="plan?.status==='DRAFT'" class="primary-btn" @click="confirmPlan">确认计划</button></div></div><div v-if="plan"><p>来源：{{plan.source}} · 状态：{{plan.status}}</p><div class="two-column"><div><h3>学期目标</h3><p v-for="goal in plan.semesterGoals||[]" :key="goal.title">{{goal.title}} <small>{{goal.abilityTag}}</small></p></div><div><h3>月度安排</h3><p v-for="item in plan.monthlyTasks||[]" :key="item.title">{{item.month}} · {{item.title}} · {{item.estimatedHours}} 小时</p></div></div></div></article><article class="card"><p class="eyebrow">目标版本</p><div class="simple-list"><div v-for="item in goalVersions" :key="item.id"><b>{{item.version || '目标版本'}}</b><span>{{item.changedAt || item.createdAt || '—'}}</span></div><p v-if="!goalVersions.length" class="empty">暂无历史版本</p></div></article></section>

  <section v-else class="development-stack"><article class="card"><p class="eyebrow">行动任务</p><h2>新建任务</h2><div class="task-form"><input v-model.trim="taskForm.title" placeholder="任务名称"><BaseSelect v-model="taskForm.type" :options="taskTypeOptions"/><input v-model="taskMonth" type="month"><input v-model="taskForm.estHours" type="number" min="0" placeholder="预计小时"><input v-model="taskForm.deadline" type="date"/><input v-model.trim="taskForm.abilityTags" placeholder="能力标签，用逗号分隔"><textarea v-model.trim="taskForm.note" placeholder="任务说明（可选）"/></div><button class="primary-btn" :disabled="!taskForm.title" @click="saveTask">创建任务</button></article><article class="card"><div class="section-head"><div><p class="eyebrow">任务清单</p><h2>持续记录进展</h2></div><div class="inline-form"><input v-model="taskMonth" type="month"><BaseSelect v-model="taskStatus" :options="taskStatusOptions"/><button class="outline-btn" @click="loadAll">筛选</button></div></div><div class="simple-list"><div v-for="task in tasks" :key="task.id"><b>{{task.title}} <small>{{task.status}}</small></b><span>{{task.month}} · {{task.estHours||0}} 小时 · {{task.note||'无备注'}}</span><div v-if="!taskEdits[task.id]" class="form-actions"><button class="outline-btn" @click="editTask(task)">编辑状态</button><button class="outline-btn" @click="checkins[task.id]={doneDesc:'',gains:'',difficulties:'',proofUrl:''}">打卡</button></div><div v-else class="task-form"><input v-model="taskEdits[task.id].title"><input v-model="taskEdits[task.id].month" type="month"><BaseSelect v-model="taskEdits[task.id].status" :options="taskStatusOptions.slice(1)"/><input v-model="taskEdits[task.id].estHours" type="number"><input v-model.trim="taskEdits[task.id].reason" placeholder="变更原因"><button class="primary-btn" @click="updateTask(task.id)">保存</button></div><div v-if="checkins[task.id]" class="task-form"><input v-model.trim="checkins[task.id].doneDesc" placeholder="完成情况"><input v-model.trim="checkins[task.id].gains" placeholder="收获"><input v-model.trim="checkins[task.id].difficulties" placeholder="困难"><input v-model.trim="checkins[task.id].proofUrl" placeholder="证明链接（可选）"><button class="primary-btn" @click="checkinTask(task.id)">提交打卡</button></div></div><p v-if="!tasks.length" class="empty">暂未创建任务</p></div></article><article class="card"><p class="eyebrow">阶段复盘</p><h2>记录阶段收获与下一步</h2><div class="task-form"><input v-model.trim="reviewForm.cycle" placeholder="复盘周期，例如 2026-09"><textarea v-model.trim="reviewForm.done" placeholder="已完成事项"/><textarea v-model.trim="reviewForm.undone" placeholder="未完成事项"/><textarea v-model.trim="reviewForm.interest" placeholder="兴趣变化"/><textarea v-model.trim="reviewForm.ability" placeholder="能力变化"/><textarea v-model.trim="reviewForm.next" placeholder="下一步计划"/></div><button class="primary-btn" :disabled="!reviewForm.cycle" @click="createReview">保存复盘草稿</button><div class="simple-list"><div v-for="review in reviews" :key="review.id"><b>{{review.cycle}} · {{review.status}}</b><span>{{review.aiSummary||'尚未生成智能总结'}}</span><div class="form-actions"><button v-if="review.status==='DRAFT'" class="outline-btn" @click="reviewAction(review.id,'submit')">提交</button><button v-if="review.status==='SUBMITTED'" class="outline-btn" @click="reviewAction(review.id,'summary')">生成总结</button><button class="outline-btn" @click="reviewAction(review.id,'guidance')">申请指导</button></div></div></div></article><article class="card"><div class="section-head"><div><p class="eyebrow">提醒</p><h2>待处理提醒</h2></div><button class="outline-btn" @click="run('reminders',api.student.generateReminders)">生成提醒</button></div><div class="simple-list"><button v-for="item in reminders" :key="item.id" @click="!item.read&&readReminder(item.id)"><b>{{item.title || item.type}}</b><span>{{item.content || item.message || '点击标记为已读'}}</span></button><p v-if="!reminders.length" class="empty">暂无提醒</p></div></article></section>
</template>
